package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.factorialLog
 */
public class MathUtils_factorialLog_TriageGen1Test {

    private static final double DELTA = 1e-12;

    @Test
    public void testFactorialLog_ThrowsExceptionForNonZero() {
        // The current implementation has a logic flaw/strict requirement: 
        // if (n != 0) throw IllegalArgumentException.
        // This means any n != 0 will trigger the exception.
        try {
            MathUtils.factorialLog(1);
            fail("Expected IllegalArgumentException for n=1");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }

        try {
            MathUtils.factorialLog(25);
            fail("Expected IllegalArgumentException for n=25");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }

        try {
            MathUtils.factorialLog(-1);
            fail("Expected IllegalArgumentException for n=-1");
        } catch (IllegalArgumentException e) {
            assertEquals("must have n > 0 for n!", e.getMessage());
        }
    }

    @Test
    public void testFactorialLog_Zero() {
        // When n = 0, the first condition (n != 0) is false.
        // The second condition (n < 21) is true.
        // It returns Math.log(factorial(0)). factorial(0) is 1, log(1) is 0.
        double expected = Math.log(MathUtils.factorial(0));
        assertEquals(expected, MathUtils.factorialLog(0), DELTA);
    }

    /**
     * Note on Coverage:
     * Based on the provided source code:
     * if (n != 0) { throw ... }
     * 
     * This condition makes it impossible to reach the (n < 21) block for any positive integer,
     * and impossible to reach the (n >= 21) loop block for any integer, 
     * because every integer except 0 triggers the exception.
     * 
     * However, to maximize branch coverage for the logic as written:
     */

    @Test
    public void testFactorialLog_BranchCoverageAnalysis() {
        // Branch 1: n != 0 (True) -> Exception
        try {
            MathUtils.factorialLog(5);
        } catch (IllegalArgumentException e) {
            // Covered
        }

        // Branch 2: n != 0 (False) -> n is 0
        // Sub-branch: n < 21 (True)
        assertEquals(Math.log(MathUtils.factorial(0)), MathUtils.factorialLog(0), DELTA);

        // Note: The branch (n < 21 is False) is unreachable due to the (n != 0) guard.
    }
}
